package apextest

import (
	"encoding/json"
	"path/filepath"
	"testing"
)

// Wave86b passed the exact original-version JSON datetime and comparison contracts.
func TestRunDatetimeOffsetContracts(t *testing.T) {
	root := t.TempDir()
	writeFile(t, filepath.Join(root, "force-app/main/default/classes/GladeOffsetDatetime53.cls"), "@IsTest private class GladeOffsetDatetime53 {\n private static Map<String,Object> describeValue(Datetime value){return new Map<String,Object>{'gmt'=>value.formatGmt('yyyy-MM-dd HH:mm:ss.SSS'),'epoch'=>value.getTime(),'gte2020'=>value>=Datetime.newInstance(2020,01,01),'gte2030'=>value>=Datetime.newInstance(2030,01,01),'lte2030'=>value<=Datetime.newInstance(2030,01,01),'lte2000'=>value<=Datetime.newInstance(2000,01,01)};}\n private static void assertObserved(Object expected,Object actual,String label){\n  if(expected instanceof Map<String,Object>){\n   System.assert(actual instanceof Map<String,Object>,label+': map type');\n   Map<String,Object> want=(Map<String,Object>)expected;Map<String,Object> got=(Map<String,Object>)actual;\n   System.assertEquals(want.keySet(),got.keySet(),label+': exact fields');\n   for(String key:want.keySet())assertObserved(want.get(key),got.get(key),label+'.'+key);\n  }else if(expected instanceof List<Object>){\n   System.assert(actual instanceof List<Object>,label+': list type');\n   List<Object> want=(List<Object>)expected;List<Object> got=(List<Object>)actual;\n   System.assertEquals(want.size(),got.size(),label+': exact size');\n   for(Integer i=0;i<want.size();i++)assertObserved(want[i],got[i],label+'['+i+']');\n  }else{\n   System.assertEquals(expected,actual,label);\n   if(expected instanceof String)System.assert(((String)expected).equals((String)actual),label+': exact text');\n  }\n }\n private static void finish(String method,List<Object> rows,Integer count){System.assertEquals(count,rows.size(),method+': complete rows');String payload=JSON.serialize(new Map<String,Object>{'done'=>true,'method'=>method,'rows'=>rows});System.assert(payload.length()<2900,method+': complete output bound');Map<String,String> expectedByMethod=new Map<String,String>{'originalAccountLastViewed'=>'{\"rows\":[{\"value\":{\"lte2000\":false,\"lte2030\":true,\"gte2030\":false,\"gte2020\":true,\"epoch\":1609495800000,\"gmt\":\"2021-01-01 10:10:00.000\"},\"name\":\"Test\",\"fieldType\":\"DATETIME\",\"input\":\"2021-01-01T10:10:00.000+0000\"}],\"method\":\"originalAccountLastViewed\",\"done\":true}','typedOffsetControls'=>'{\"rows\":[{\"value\":{\"lte2000\":false,\"lte2030\":true,\"gte2030\":false,\"gte2020\":true,\"epoch\":1609495800000,\"gmt\":\"2021-01-01 10:10:00.000\"},\"input\":\"2021-01-01T10:10:00.000+0000\"},{\"value\":{\"lte2000\":false,\"lte2030\":true,\"gte2030\":false,\"gte2020\":true,\"epoch\":1609495800000,\"gmt\":\"2021-01-01 10:10:00.000\"},\"input\":\"2021-01-01T10:10:00.000Z\"},{\"value\":{\"lte2000\":false,\"lte2030\":true,\"gte2030\":false,\"gte2020\":true,\"epoch\":1609476000000,\"gmt\":\"2021-01-01 04:40:00.000\"},\"input\":\"2021-01-01T10:10:00.000+0530\"},{\"value\":{\"lte2000\":false,\"lte2030\":true,\"gte2030\":false,\"gte2020\":true,\"epoch\":1609524600000,\"gmt\":\"2021-01-01 18:10:00.000\"},\"input\":\"2021-01-01T10:10:00.000-0800\"}],\"method\":\"typedOffsetControls\",\"done\":true}'};System.assert(expectedByMethod.containsKey(method),method+': expected case exists');assertObserved(JSON.deserializeUntyped(expectedByMethod.get(method)),JSON.deserializeUntyped(payload),method);}\n @IsTest static void originalAccountLastViewed(){\n  List<Object> rows=new List<Object>();\n  Map<String,Object> row=new Map<String,Object>{'input'=>'2021-01-01T10:10:00.000+0000','fieldType'=>String.valueOf(Account.LastViewedDate.getDescribe().getType())};\n  try{\n   Account record=(Account)JSON.deserialize('{\"attributes\":{\"type\":\"Account\"},\"Name\":\"Test\", \"LastViewedDate\":\"2021-01-01T10:10:00.000+0000\"}',Account.class);\n   row.put('name',record.Name);row.put('value',describeValue(record.LastViewedDate));\n  }catch(Exception error){row.put('type',error.getTypeName());row.put('message',error.getMessage());}\n  rows.add(row);finish('originalAccountLastViewed',rows,1);\n }\n @IsTest static void typedOffsetControls(){\n  List<Object> rows=new List<Object>();\n  for(String input:new List<String>{'2021-01-01T10:10:00.000+0000','2021-01-01T10:10:00.000Z','2021-01-01T10:10:00.000+0530','2021-01-01T10:10:00.000-0800'}){\n   Map<String,Object> row=new Map<String,Object>{'input'=>input};\n   try{Datetime value=(Datetime)JSON.deserialize(JSON.serialize(input),Datetime.class);row.put('value',describeValue(value));}catch(Exception error){row.put('type',error.getTypeName());row.put('message',error.getMessage());}\n   rows.add(row);\n  }\n  finish('typedOffsetControls',rows,4);\n }\n}\n")
	writeFile(t, filepath.Join(root, "force-app/main/default/classes/GladeOffsetDatetime53.cls-meta.xml"), "<ApexClass xmlns=\"http://soap.sforce.com/2006/04/metadata\"><apiVersion>53.0</apiVersion><status>Active</status></ApexClass>\n")
	writeFile(t, filepath.Join(root, "sfdx-project.json"), "{\"sourceApiVersion\": \"53.0\", \"packageDirectories\": [{\"path\": \"force-app\", \"default\": true}]}")
	run := Run(loadTestIndex(t, root), Options{})
	if got := run.Summary(); got.Total != 2 || got.Passed != 2 || got.Failed != 0 || got.Errors != 0 || got.Skipped != 0 {
		data, _ := json.Marshal(run)
		t.Fatalf("datetime offset contracts failed: %s", data)
	}
}
